SELECT * FROM proj_project_member_assignment WHERE project_id = #{query.projectId} AND member_role = #{query.memberRole}
AND (assignment_type = 'PRIMARY' OR assignment_type IS NULL)
AND assignment_type = #{query.assignmentType}
AND ((site_id = #{query.siteId}) OR (site_id IS NULL AND #{query.siteId} IS NULL)) AND status = 'ACTIVE' AND deleted = b'0' AND (effective_from IS NULL OR effective_from <= #{query.effectiveAt}) AND (effective_to IS NULL OR effective_to > #{query.effectiveAt}) ORDER BY id FOR UPDATE
